  IF EXISTS (SELECT 1 FROM public."Client") OR EXISTS (SELECT 1 FROM public."Feature") OR EXISTS (SELECT 1 FROM public."Oem") THEN
    RAISE EXCEPTION 'Seed snapshot requires a freshly migrated, empty database';
  END IF;
END $$;
SET LOCAL session_replication_role = replica;

